 bool reserved(QString p){for(auto t:jobs)if(t->path.compare(p,Qt::CaseInsensitive)==0)return true;return QFile::exists(p)||QFile::exists(p+".halab.json");}
 QString available(QString folder,QString name){return DownloadNames::unique(folder,name,[this](QString path){return reserved(path);});}

 void addDialog(){QDialog d(this);d.setMinimumWidth(560);d.setWindowTitle("Add download");auto f=new QFormLayout(&d);f->setContentsMargins(28,28,28,28);f->setSpacing(18);auto url=new QLineEdit;url->setLayoutDirection(Qt::LeftToRight);auto folder=new QLineEdit(defaultFolder);auto pick=new QPushButton("Browse...");auto row=new QHBoxLayout;row->addWidget(folder);row->addWidget(pick);connect(pick,&QPushButton::clicked,&d,[&]{QString p=QFileDialog::getExistingDirectory(&d,"Save to",folder->text());if(!p.isEmpty())folder->setText(p);});auto name=new QLineEdit;name->setPlaceholderText("Use filename from URL");auto count=new QSpinBox;count->setRange(1,16);count->setValue(defaultConnections);auto schedule=new QCheckBox("Start at");auto date=new QDateTimeEdit(QDateTime::currentDateTime().addSecs(3600));date->setCalendarPopup(true);auto queued=new QCheckBox("Download later");f->addRow("Address",url);f->addRow("Save to",row);f->addRow("Filename",name);f->addRow("Connections",count);f->addRow(schedule,date);f->addRow(queued);auto buttons=new QDialogButtonBox(QDialogButtonBox::Ok|QDialogButtonBox::Cancel);f->addRow(buttons);connect(buttons,&QDialogButtonBox::rejected,&d,&QDialog::reject);connect(buttons,&QDialogButtonBox::accepted,&d,[&]{QUrl u(url->text().trimmed());if(!u.isValid()||!QStringList{"http","https"}.contains(u.scheme())||u.host().isEmpty()){QMessageBox::warning(&d,"Invalid address","Enter a valid HTTP or HTTPS URL.");return;}QString filename=name->text().trimmed();if(filename.isEmpty())filename=QFileInfo(u.path()).fileName();add(u.toString(),available(folder->text(),filename),count->value(),schedule->isChecked()?date->dateTime():QDateTime());jobs.last()->automaticName=name->text().trimmed().isEmpty();if(queued->isChecked())jobs.last()->state="paused";d.accept();});d.exec();}
