 void removeRows(QList<int> rows,bool deleteDisk){std::sort(rows.begin(),rows.end(),std::greater<int>());QStringList failures;{QSignalBlocker selectionSignals(table->selectionModel());for(int i:rows){if(i<0||i>=jobs.size())continue;auto t=jobs[i];t->pause();if(deleteDisk&&QFile::exists(t->path)&&!QFile::remove(t->path)){failures.append(t->path);continue;}jobs.removeAt(i);retryAt.remove(t);attempts.remove(t);QObject::disconnect(t,nullptr,this,nullptr);t->reservedName={};t->halt("paused");t->discarded=true;if(deleteDisk){QFile::remove(t->meta());for(int part=0;part<16;++part)QFile::remove(t->partPath(part));}t->deleteLater();}}refresh();save();if(!failures.isEmpty())QMessageBox::warning(this,L::text("Could not delete files"),L::text("These files could not be deleted. Their download entries were kept:")+"\n"+failures.join("\n"));}
