 void pump(){auto now=QDateTime::currentDateTime();if(schedulerEnabled){if(queueStart.isValid()&&now>=queueStart){startQueue();queueStart={};}if(queueStop.isValid()&&now>=queueStop){stopQueue();queueStop={};schedulerEnabled=false;}}if(!queueRunning)return;for(auto t:jobs)if(t->state=="error"&&retryAt.contains(t)&&retryAt[t]<=now){t->state="queued";retryAt.remove(t);}int active=0;for(auto t:jobs)if(t->state=="running"||t->state=="probing")++active;for(auto t:jobs){if(active>=parallel->value())break;if(t->state=="queued"&&(!t->scheduled.isValid()||t->scheduled<=now)){t->start();if(t->state=="running"||t->state=="probing")++active;}}}
 void refresh(){QSignalBlocker tableSignals(table);QSignalBlocker selectionSignals(table->selectionModel());table->setRowCount(jobs.size());double speed=0;int done=0,visibleRows=0;QFileIconProvider icons;auto current=categories->currentItem();QString key=current?current->data(0,Qt::UserRole).toString():"all";for(int i=0;i<jobs.size();++i){auto t=jobs[i];speed+=t->speed;done+=t->state=="done";int percent=t->state=="done"?100:t->total>0?qMin(100,int(double(t->received)*100/t->total)):0;QStringList vals{QFileInfo(t->path).fileName(),t->state=="done"?"":"1",t->total<0?bytes(t->received):bytes(t->total),label(t->state),t->speed>0&&t->total>0?QString::number(qMax<qint64>(0,qint64((t->total-t->received)/t->speed)))+" s":"",t->speed>0?bytes(qint64(t->speed))+"/s":"",QString::number(percent)+"%",t->scheduled.isValid()?t->scheduled.toString("yyyy-MM-dd HH:mm"):"",t->url,t->path};for(int j=0;j<vals.size();++j){if(!table->item(i,j)){table->setItem(i,j,new QTableWidgetItem);}auto item=table->item(i,j);if(j==0)item->setIcon(categoryIcon(fileCategory(t->path)));item->setText(vals[j]);item->setToolTip(t->error.isEmpty()?t->url+"\n"+t->path:t->error);if(j==3)item->setForeground(QColor(t->state=="error"?"#f29292":t->state=="done"?"#b7d3c6":"#dce0e6"));}bool visible=search->text().isEmpty()||(t->url+t->path).contains(search->text(),Qt::CaseInsensitive);if(key=="unfinished"||key=="queue")visible&=t->state!="done";if(key=="finished")visible&=t->state=="done";if(key=="grabber")visible&=t->origin=="grabber";if(key.startsWith("type:"))visible&=fileCategory(t->path)==key.mid(5);table->setRowHidden(i,!visible);visibleRows+=visible;}summary->setText(L::text("%1 downloads · %2 shown · %3 complete · %4/s · Queue: %5").arg(jobs.size()).arg(visibleRows).arg(done).arg(bytes(qint64(speed))).arg(L::text(queueRunning?"Running":"Stopped")));bool selected=table->selectionModel()->hasSelection();for(auto action:{resumeAction,stopAction,deleteAction,detailsAction})if(action)action->setEnabled(selected);}

 void save(){QJsonArray a;for(auto t:jobs)a.append(QJsonObject{{"url",t->url},{"path",t->path},{"storagePath",t->storagePath},{"automaticName",t->automaticName},{"connections",t->connections},{"origin",t->origin},{"mediaJob",t->mediaJob},{"mediaFormat",t->mediaFormat},{"mediaToken",t->mediaToken},{"mediaTitle",t->mediaTitle},{"state",t->state},{"scheduled",t->scheduled.toString(Qt::ISODate)},{"total",QString::number(t->total)},{"received",QString::number(t->received)}});setProperty("saveOk",false);QSaveFile f(store);if(f.open(QIODevice::WriteOnly)){f.write(QJsonDocument(QJsonObject{{"parallel",parallel->value()},{"language",language},{"jobs",a},{"connections",defaultConnections},{"folder",defaultFolder},{"retryLimit",retryLimit},{"speedLimitKiB",speedLimitKiB},{"schedulerEnabled",schedulerEnabled},{"queueRunning",queueRunning},{"queueStart",queueStart.toString(Qt::ISODate)},{"queueStop",queueStop.toString(Qt::ISODate)},{"proxyType",int(configuredProxy.type())},{"proxyHost",configuredProxy.hostName()},{"proxyPort",configuredProxy.port()}}).toJson());if(!f.commit())statusBar()->showMessage("Could not save settings: "+f.errorString());else setProperty("saveOk",true);}}
 void load(){QFile f(store);if(!f.open(QIODevice::ReadOnly))return;auto o=QJsonDocument::fromJson(f.readAll()).object();language=o["language"].toString("ar");parallel->setValue(o["parallel"].toInt(2));defaultConnections=qBound(1,o["connections"].toInt(4),16);defaultFolder=o["folder"].toString(defaultFolder);retryLimit=qBound(0,o["retryLimit"].toInt(),5);speedLimitKiB=qBound(0,o["speedLimitKiB"].toInt(),1048576);schedulerEnabled=o["schedulerEnabled"].toBool();queueStart=QDateTime::fromString(o["queueStart"].toString(),Qt::ISODate);queueStop=QDateTime::fromString(o["queueStop"].toString(),Qt::ISODate);if(schedulerEnabled){auto now=QDateTime::currentDateTime();queueRunning=!queueStart.isValid()&&queueStop.isValid()&&now<queueStop&&o["queueRunning"].toBool(true);if(!queueStop.isValid()||now>=queueStop){schedulerEnabled=false;queueRunning=false;queueStart={};queueStop={};}}int pt=o["proxyType"].toInt(int(QNetworkProxy::DefaultProxy));if(pt!=QNetworkProxy::DefaultProxy&&pt!=QNetworkProxy::NoProxy&&pt!=QNetworkProxy::HttpProxy&&pt!=QNetworkProxy::Socks5Proxy)pt=QNetworkProxy::DefaultProxy;configuredProxy=QNetworkProxy(QNetworkProxy::ProxyType(pt),o["proxyHost"].toString(),quint16(o["proxyPort"].toInt(8080)));for(auto v:o["jobs"].toArray()){auto j=v.toObject();auto t=new Transfer(j["url"].toString(),j["path"].toString(),qBound(1,j["connections"].toInt(4),16));t->setParent(this);t->storagePath=j["storagePath"].toString(t->path);t->automaticName=j["automaticName"].toBool(QFileInfo(t->path).suffix().isEmpty());t->origin=j["origin"].toString();t->mediaJob=j["mediaJob"].toBool();t->mediaFormat=j["mediaFormat"].toString();t->mediaToken=j["mediaToken"].toString(t->mediaToken);t->mediaTitle=j["mediaTitle"].toString();t->state=j["state"].toString()=="done"?"done":schedulerEnabled&&queueRunning?"queued":"paused";t->scheduled=QDateTime::fromString(j["scheduled"].toString(),Qt::ISODate);t->total=j["total"].toString().toLongLong();t->received=j["received"].toString().toLongLong();jobs.append(t);watch(t);}}
 QString fileCategory(QString file)const{QString ext=QFileInfo(file).suffix().toLower();if(QStringList{"zip","rar","7z","gz","tar","bz2","xz"}.contains(ext))return "Compressed";if(QStringList{"mp3","wav","ogg","flac","m4a","aac"}.contains(ext))return "Music";if(QStringList{"mp4","mkv","webm","avi","mov","wmv"}.contains(ext))return "Video";if(QStringList{"exe","msi","msix","apk","dmg","deb"}.contains(ext))return "Programs";return "Documents";}
 void resumeSelected(){selected([this](Transfer*t){if(t->state=="paused"||t->state=="error"){t->state="queued";retryAt.remove(t);attempts.remove(t);}});queueRunning=true;}
 void startQueue(){queueRunning=true;for(auto t:jobs)if(t->state=="paused")t->state="queued";refresh();save();}
 void stopQueue(){queueRunning=false;retryAt.clear();for(auto t:jobs)t->pause();refresh();save();}
 void clearCompleted(){QList<int> rows;for(int i=0;i<jobs.size();++i)if(jobs[i]->state=="done")rows.append(i);confirmRemoval(rows);}

 void batchDialog(){QDialog d(this);d.setWindowTitle("Add batch download");d.setMinimumWidth(610);QFormLayout form(&d);QLineEdit pattern;pattern.setPlaceholderText("https://example.com/file[01-12].zip");QLabel hint("Use one numeric range such as [01-12]. Up to 500 files will be queued, preserving zero padding.");hint.setWordWrap(true);form.addRow(&hint);form.addRow("URL pattern",&pattern);QDialogButtonBox buttons(QDialogButtonBox::Ok|QDialogButtonBox::Cancel);form.addRow(&buttons);connect(&buttons,&QDialogButtonBox::rejected,&d,&QDialog::reject);connect(&buttons,&QDialogButtonBox::accepted,&d,[&]{QString input=pattern.text().trimmed();QRegularExpression rx(R"(\[(\d{1,6})-(\d{1,6})\])");auto match=rx.match(input);if(!match.hasMatch()){QMessageBox::warning(&d,"Batch","Enter one numeric range, for example [01-12].");return;}int first=match.captured(1).toInt(),last=match.captured(2).toInt();if(last<first||last-first>=500){QMessageBox::warning(&d,"Batch","Use an ascending range of at most 500 files.");return;}QList<QUrl> urls;for(int i=first;i<=last;++i){QString address=input;address.replace(match.capturedStart(),match.capturedLength(),QString::number(i).rightJustified(match.captured(1).size(),'0'));QUrl u(address);if(!u.isValid()||!QStringList{"http","https"}.contains(u.scheme())||u.host().isEmpty()){QMessageBox::warning(&d,"Batch","The pattern must produce valid HTTP or HTTPS URLs.");return;}urls.append(u);}auto folder=QFileDialog::getExistingDirectory(&d,"Save batch downloads to",defaultFolder);if(folder.isEmpty())return;for(auto u:urls){add(u.toString(),available(folder,QFileInfo(u.path()).fileName()),defaultConnections);jobs.last()->state="paused";}refresh();save();d.accept();});d.exec();}

