 void details(){auto rows=table->selectionModel()->selectedRows();if(rows.isEmpty())return;QPointer<Transfer>t=jobs[rows.first().row()];QDialog d(this);d.setWindowTitle("Download properties");d.resize(650,410);QVBoxLayout layout(&d);QLabel name;name.setTextFormat(Qt::PlainText);name.setWordWrap(true);layout.addWidget(&name);QProgressBar overall;layout.addWidget(&overall);QTableWidget parts(0,3);parts.setHorizontalHeaderLabels({"Connection","Downloaded","Segment size"});parts.horizontalHeader()->setSectionResizeMode(QHeaderView::Stretch);parts.setEditTriggers(QAbstractItemView::NoEditTriggers);layout.addWidget(&parts,1);QLabel message;message.setTextFormat(Qt::PlainText);message.setWordWrap(true);layout.addWidget(&message);auto update=[&]{if(!t){d.reject();return;}name.setText(QFileInfo(t->path).fileName()+"\n"+t->url+"\n"+t->path);overall.setValue(t->state=="done"?100:t->total>0?int(double(t->received)*100/t->total):0);parts.setRowCount(int(t->parts.size()));for(int i=0;i<int(t->parts.size());++i){auto&p=*t->parts[i];QStringList values{QString::number(i+1),bytes(p.done),p.end>=p.start?bytes(p.end-p.start+1):L::text("Unknown")};for(int j=0;j<3;++j){if(!parts.item(i,j))parts.setItem(i,j,new QTableWidgetItem);parts.item(i,j)->setText(values[j]);}}message.setText(label(t->state)+"\n"+L::text("Resume support")+": "+L::text(t->ranged?"Supported":t->state=="probing"||t->state=="queued"?"Checking":"Not confirmed")+(t->error.isEmpty()?"":"\n"+L::text(t->error)));};QDialogButtonBox buttons(QDialogButtonBox::Close);layout.addWidget(&buttons);connect(&buttons,&QDialogButtonBox::rejected,&d,&QDialog::reject);QTimer timer;connect(&timer,&QTimer::timeout,&d,update);timer.start(300);update();d.exec();}
 void grabber(){QDialog d(this);d.setWindowTitle("Site Grabber — Page links");d.resize(750,540);QVBoxLayout layout(&d);QHBoxLayout row;QLineEdit address;address.setPlaceholderText("https://example.com/downloads");QPushButton scan("Find links");row.addWidget(&address,1);row.addWidget(&scan);layout.addLayout(&row);QLabel note("Find links on one public page, then select files to add to the queue. JavaScript pages and video streams are not supported.");note.setWordWrap(true);layout.addWidget(&note);QListWidget links;links.setSelectionMode(QAbstractItemView::ExtendedSelection);layout.addWidget(&links,1);QDialogButtonBox buttons(QDialogButtonBox::Close);auto import=buttons.addButton("Queue selected links",QDialogButtonBox::ActionRole);layout.addWidget(&buttons);QNetworkAccessManager net;net.setProxy(configuredProxy);QPointer<QNetworkReply>reply;connect(&buttons,&QDialogButtonBox::rejected,&d,&QDialog::reject);
 connect(&scan,&QPushButton::clicked,&d,[&]{QUrl u(address.text().trimmed());if(!u.isValid()||!QStringList{"http","https"}.contains(u.scheme())||u.host().isEmpty()){note.setText("Enter a valid HTTP or HTTPS address.");return;}links.clear();scan.setEnabled(false);QNetworkRequest req(u);req.setTransferTimeout(20000);reply=net.get(req);reply->setReadBufferSize(2*1024*1024);auto html=std::make_shared<QByteArray>();connect(reply,&QNetworkReply::readyRead,&d,[&,html]{if(!reply)return;html->append(reply->readAll());if(html->size()>2*1024*1024){note.setText("Page exceeds the 2 MB limit.");reply->abort();}});connect(reply,&QNetworkReply::finished,&d,[&,html]{scan.setEnabled(true);if(!reply)return;auto r=reply.data();reply=nullptr;if(r->error()!=QNetworkReply::NoError){note.setText(r->errorString());r->deleteLater();return;}html->append(r->readAll());QUrl base=r->url();r->deleteLater();QSet<QString>seen;QRegularExpression pattern("(?:href|src)\\s*=\\s*[\\\"']([^\\\"'<>]+)[\\\"']",QRegularExpression::CaseInsensitiveOption);auto matches=pattern.globalMatch(QString::fromUtf8(*html));while(matches.hasNext()&&seen.size()<2000){QString path=matches.next().captured(1);path.replace("&amp;","&");QUrl link=base.resolved(QUrl(path));link.setFragment({});if(link.isValid()&&QStringList{"http","https"}.contains(link.scheme())&&!link.host().isEmpty()&&!seen.contains(link.toString())){seen.insert(link.toString());links.addItem(link.toString());}}note.setText(L::text("Found %1 links. Select desired files; only selected URLs will be queued.").arg(links.count()));});});connect(import,&QPushButton::clicked,&d,[&]{auto selected=links.selectedItems();if(selected.isEmpty())return;auto folder=QFileDialog::getExistingDirectory(&d,"Save downloads to",defaultFolder);if(folder.isEmpty())return;for(auto item:selected){QUrl u(item->text());add(u.toString(),available(folder,QFileInfo(u.path()).fileName()),defaultConnections);jobs.last()->state="paused";jobs.last()->origin="grabber";}refresh();save();note.setText(L::text("Added %1 links to the queue.").arg(selected.size()));});d.exec();if(reply)reply->abort();}
 bool uiChecks(){tick.stop();queueRunning=false;show();QCoreApplication::processEvents();QString dir=QFileInfo(store).absolutePath();add("https://example.invalid/archive.zip",dir+"/archive.zip",4);add("https://example.invalid/movie.mp4",dir+"/movie.mp4",4);jobs[0]->state="done";jobs[0]->total=1024;jobs[1]->state="paused";auto all=categories->topLevelItem(0);categories->setCurrentItem(all->child(0));refresh();bool category=!table->isRowHidden(0)&&table->isRowHidden(1);categories->setCurrentItem(categories->topLevelItem(1));refresh();bool unfinished=table->isRowHidden(0)&&!table->isRowHidden(1);categories->setCurrentItem(all);search->setText("movie");refresh();bool searching=table->isRowHidden(0)&&!table->isRowHidden(1);search->clear();table->selectionModel()->select(table->model()->index(1,0),QItemSelectionModel::ClearAndSelect|QItemSelectionModel::Rows);bool selection=resumeAction->isEnabled();resumeSelected();bool resume=jobs[1]->state=="queued";stopQueue();bool stopped=jobs[1]->state=="paused"&&!queueRunning;startQueue();bool queued=jobs[1]->state=="queued"&&queueRunning;stopQueue();schedulerEnabled=true;queueStart=QDateTime::currentDateTime().addSecs(60);queueStop=QDateTime::currentDateTime().addSecs(120);defaultConnections=8;retryLimit=2;save();QFile f(store);if(!f.open(QIODevice::ReadOnly)){QTextStream(stderr)<<store<<": "<<f.errorString()<<Qt::endl;return false;}auto o=QJsonDocument::fromJson(f.readAll()).object();f.close();bool persistence=o["connections"].toInt()==8&&o["schedulerEnabled"].toBool()&&o["jobs"].toArray().size()==2;QTextStream(stdout)<<"UI checks: category="<<category<<" unfinished="<<unfinished<<" search="<<searching<<" selection="<<selection<<" resume="<<resume<<" stop="<<stopped<<" queue="<<queued<<" persistence="<<persistence<<Qt::endl;for(auto t:jobs)t->state="done";schedulerEnabled=true;queueStart=QDateTime::currentDateTime().addSecs(-10);queueStop=QDateTime::currentDateTime().addSecs(-1);pump();bool scheduleEvents=!queueRunning&&!schedulerEnabled&&!queueStart.isValid()&&!queueStop.isValid();save();Window restored(store);restored.tick.stop();bool reload=restored.defaultConnections==8&&restored.retryLimit==2&&restored.jobs.size()==2;QTextStream(stdout)<<"UI checks: schedule events="<<scheduleEvents<<" settings reload="<<reload<<Qt::endl;schedulerEnabled=true;queueStart={};queueStop=QDateTime::currentDateTime().addSecs(120);queueRunning=true;jobs[1]->state="paused";save();Window active(store);active.tick.stop();bool activeRestore=active.queueRunning&&active.jobs[1]->state=="queued";QTextStream(stdout)<<"UI checks: active schedule restored="<<activeRestore<<Qt::endl;return category&&unfinished&&searching&&selection&&resume&&stopped&&queued&&persistence&&scheduleEvents&&reload&&activeRestore;}


 void applyLanguage(){L::setLanguage(language);setLayoutDirection(language=="ar"?Qt::RightToLeft:Qt::LeftToRight);L::apply(this);if(auto dock=findChild<QDockWidget*>("categoryDock")){addDockWidget(language=="ar"?Qt::RightDockWidgetArea:Qt::LeftDockWidgetArea,dock);resizeDocks({dock},{230},Qt::Horizontal);}if(auto menu=findChild<QMenu*>("languageMenu"))for(auto action:menu->actions())action->setChecked(action->data().toString()==language);refresh();}
