 void changeLanguage(QString value){language=QStringList{"ar","en","tr"}.contains(value)?value:"en";applyLanguage();}
 void repairExtension(){selected([this](Transfer*t){if(t->state!="done"||!QFile::exists(t->path))return;QString ext=QMimeDatabase().mimeTypeForFile(t->path,QMimeDatabase::MatchContent).preferredSuffix();if(ext.isEmpty()){QMessageBox::information(this,L::text("Detect file extension"),L::text("No known file type could be detected."));return;}if(QFileInfo(t->path).suffix().compare(ext,Qt::CaseInsensitive)==0)return;QString target=DownloadNames::unique(QFileInfo(t->path).absolutePath(),QFileInfo(t->path).completeBaseName()+"."+ext,[this](QString path){return reserved(path);});if(QFile::rename(t->path,target))t->path=target;else QMessageBox::warning(this,L::text("Detect file extension"),L::text("Could not rename the file."));});}

 bool languageChecks(){tick.stop();bool good=true;for(QString code:QStringList{"ar","en","tr"}){changeLanguage(code);show();QCoreApplication::processEvents();auto title=categories->topLevelItem(0)->text(0);QString expected=code=="ar"?"جميع التنزيلات":code=="tr"?"Tüm İndirmeler":"All Downloads";QTextStream(stdout)<<"LANG "<<code<<" title="<<title<<" expected="<<expected<<" direction="<<layoutDirection()<<Qt::endl;good&=title==expected&&layoutDirection()==(code=="ar"?Qt::RightToLeft:Qt::LeftToRight);for(auto bar:findChildren<QToolBar*>())for(auto action:bar->actions())if(auto button=qobject_cast<QToolButton*>(bar->widgetForAction(action)))if(button->width()<button->fontMetrics().horizontalAdvance(action->text())+20){good=false;QTextStream(stdout)<<"WIDTH "<<action->text()<<" actual="<<button->width()<<" needed="<<button->fontMetrics().horizontalAdvance(action->text())+20<<Qt::endl;}}language="tr";save();Window restored(store);restored.tick.stop();good&=restored.language=="tr";QTextStream(stdout)<<"Language and toolbar checks: "<<good<<Qt::endl;return good;}
 QJsonObject receiveExternal(QJsonObject request){QString op=request["op"].toString(),url=request["url"].toString();if(op=="show"){showNormal();raise();activateWindow();return {{"ok",true}};}if(!HalabTools::validUrl(url)||!QStringList{"download","video"}.contains(op))return {{"ok",false},{"error","Invalid download request"}};QString name=DownloadNames::clean(request["name"].toString());if(name=="download")name=QFileInfo(QUrl(url).path()).fileName();add(url,available(defaultFolder,name),defaultConnections);auto t=jobs.last();if(op=="video"){QString format=request["formatId"].toString();if(!QRegularExpression("^[A-Za-z0-9_.-]{1,80}$").match(format).hasMatch()){jobs.removeLast();t->deleteLater();return {{"ok",false},{"error","Invalid format"}};}t->mediaJob=true;t->mediaFormat=format;t->mediaTitle=request["title"].toString();t->origin=request["needsMerge"].toBool()?"browser-video-merge":"browser-video";}else t->origin="browser";save();if(!property("saveOk").toBool()){jobs.removeLast();t->deleteLater();return {{"ok",false},{"error","Could not save the download queue"}};}show();raise();activateWindow();refresh();return {{"ok",true},{"queued",true},{"name",QFileInfo(t->path).fileName()}};}
 void shutdown(){if(closing)return;closing=true;tick.stop();for(auto t:jobs)t->pause();save();}
 void closeEvent(QCloseEvent*e)override{if(property("backgroundCapable").toBool()&&!closing){hide();e->ignore();return;}shutdown();e->accept();}
 bool deletionChecks(){tick.stop();queueRunning=false;show();QCoreApplication::processEvents();auto dir=QFileInfo(store).absolutePath();auto addFile=[&](QString name){QFile file(dir+"/"+name);if(!file.open(QIODevice::WriteOnly))return false;file.write("original download");file.close();add("https://example.invalid/"+name,file.fileName(),4);jobs.last()->state="done";refresh();return true;};bool defaults=true;auto answer=[&](bool yes,bool disk){QTimer::singleShot(0,this,[&,yes,disk]{auto box=qobject_cast<QMessageBox*>(QApplication::activeModalWidget());if(!box)return;defaults&=box->defaultButton()==box->button(QMessageBox::No)&&box->checkBox()&&!box->checkBox()->isChecked();box->checkBox()->setChecked(disk);box->button(yes?QMessageBox::Yes:QMessageBox::No)->click();});};if(!addFile("kept.zip"))return false;table->selectionModel()->select(table->model()->index(0,0),QItemSelectionModel::ClearAndSelect|QItemSelectionModel::Rows);answer(false,true);remove();bool cancelled=jobs.size()==1&&QFile::exists(dir+"/kept.zip");table->selectionModel()->select(table->model()->index(0,0),QItemSelectionModel::ClearAndSelect|QItemSelectionModel::Rows);answer(true,false);remove();bool kept=jobs.isEmpty()&&QFile::exists(dir+"/kept.zip");QTextStream(stdout)<<"KEEP jobs="<<jobs.size()<<" file="<<QFile::exists(dir+"/kept.zip")<<" selected="<<table->selectionModel()->selectedRows().size()<<Qt::endl;if(!addFile("deleted.zip"))return false;table->selectionModel()->select(table->model()->index(0,0),QItemSelectionModel::ClearAndSelect|QItemSelectionModel::Rows);answer(true,true);remove();QCoreApplication::sendPostedEvents(nullptr,QEvent::DeferredDelete);bool deleted=jobs.isEmpty()&&!QFile::exists(dir+"/deleted.zip");QTextStream(stdout)<<"DELETE cancel="<<cancelled<<" keepDisk="<<kept<<" deleteDisk="<<deleted<<" safeDefaults="<<defaults<<Qt::endl;return cancelled&&kept&&deleted&&defaults;}
 bool lifecycleChecks(){tick.stop();queueRunning=false;auto dir=QFileInfo(store).absolutePath();QFile existing(dir+"/keep.zip");if(!existing.open(QIODevice::WriteOnly))return false;existing.write("keep");existing.close();for(int i=0;i<5;++i)add("https://example.invalid/file.zip",i==0?existing.fileName():dir+"/file"+QString::number(i)+".zip",4);jobs[0]->state="done";jobs[1]->state="running";jobs[2]->state="paused";jobs[3]->state="error";jobs[4]->state="done";refresh();auto select=[&](int row){table->selectionModel()->select(table->model()->index(row,0),QItemSelectionModel::Select|QItemSelectionModel::Rows);};select(0);select(1);select(3);QTextStream(stdout)<<"Selected="<<table->selectionModel()->selectedRows().size()<<Qt::endl;removeRows([&]{QList<int> rows;for(auto idx:table->selectionModel()->selectedRows())rows.append(idx.row());return rows;}(),false);QTextStream(stdout)<<"Remaining="<<jobs.size()<<" states="<<(jobs.size()>0?jobs[0]->state:QString())<<","<<(jobs.size()>1?jobs[1]->state:QString())<<" file="<<QFile::exists(existing.fileName())<<Qt::endl;bool removed=jobs.size()==2&&jobs[0]->state=="paused"&&jobs[1]->state=="done"&&QFile::exists(existing.fileName());select(1);removeRows({1},false);bool cleared=jobs.size()==1;select(0);removeRows([&]{QList<int> rows;for(auto idx:table->selectionModel()->selectedRows())rows.append(idx.row());return rows;}(),false);bool empty=jobs.isEmpty()&&table->rowCount()==0;QCoreApplication::sendPostedEvents(nullptr,QEvent::DeferredDelete);add("https://example.invalid/new.zip",dir+"/new.zip",4);jobs[0]->state="paused";setProperty("backgroundCapable",true);show();close();bool hidden=!isVisible()&&!closing&&jobs[0]->state=="paused";show();bool restored=isVisible();shutdown();QTextStream(stdout)<<"LIFECYCLE remove="<<removed<<" clear="<<cleared<<" empty="<<empty<<" closeToTray="<<hidden<<" reopen="<<restored<<Qt::endl;return removed&&cleared&&empty&&hidden&&restored;}
