int main(int argc,char**argv){QApplication app(argc,argv);L::DialogFilter languageFilter;app.installEventFilter(&languageFilter);app.setOrganizationName("Mahmud Abbas");app.setApplicationName("HalabDownloadManager");auto args=app.arguments();if(args.contains("--fetch")){int i=args.indexOf("--fetch");if(args.size()<i+3)return 2;Transfer t(args[i+1],QFileInfo(args[i+2]).absoluteFilePath());if(args.contains("--auto-name"))t.automaticName=true;if(args.contains("--limit-kib")){int l=args.indexOf("--limit-kib");if(l+1<args.size())t.rateLimit=qMax(0,args[l+1].toInt())*qint64(1024);}QObject::connect(&t,&Transfer::ended,&app,[&](bool ok){QTextStream(stdout)<<(ok?"OK":t.error)<<Qt::endl;if(ok)QTextStream(stdout)<<"FILE="<<t.path<<Qt::endl;app.exit(ok?0:1);});if(args.contains("--pause-after")){int p=args.indexOf("--pause-after");if(p+1<args.size())QTimer::singleShot(args[p+1].toInt(),&app,[&]{t.pause();app.exit(3);});}QTimer::singleShot(0,&t,[&]{t.start();});return app.exec();}if(args.contains("--delete-check")){QTemporaryDir temp;Window test(temp.path()+"/downloads.json");return test.deletionChecks()?0:1;}if(args.contains("--lifecycle-check")){QTemporaryDir temp;Window test(temp.path()+"/downloads.json");return test.lifecycleChecks()?0:1;}if(args.contains("--language-check")){QTemporaryDir temp;Window test(temp.path()+"/downloads.json");return test.languageChecks()?0:1;}if(args.contains("--ui-check")){QTemporaryDir temp;Window test(temp.path()+"/downloads.json");return test.uiChecks()?0:1;}QDir().mkpath(HalabTools::profile());QLockFile instanceLock(HalabTools::profile()+"/instance.lock");if(!args.contains("--preview")&&!instanceLock.tryLock(100)){if(!args.contains("--background")&&!args.contains("--listen")){QFile file(HalabTools::profile()+"/connector.json");if(file.open(QIODevice::ReadOnly)){auto c=QJsonDocument::fromJson(file.readAll()).object();QTcpSocket socket;socket.connectToHost(QHostAddress::LocalHost,quint16(c["port"].toInt()));if(socket.waitForConnected(1000)){socket.write(QJsonDocument(QJsonObject{{"op","show"},{"_token",c["token"]}}).toJson(QJsonDocument::Compact)+"\n");socket.waitForBytesWritten(1000);}}}return 0;}QTcpServer server;QString connectorToken=QUuid::createUuid().toString(QUuid::Id128)+QUuid::createUuid().toString(QUuid::Id128);if(!args.contains("--preview")){if(!server.listen(QHostAddress::LocalHost,0))return 4;QSaveFile connector(HalabTools::profile()+"/connector.json");if(!connector.open(QIODevice::WriteOnly))return 5;connector.setPermissions(QFile::ReadOwner|QFile::WriteOwner);connector.write(QJsonDocument(QJsonObject{{"port",server.serverPort()},{"token",connectorToken},{"pid",QCoreApplication::applicationPid()}}).toJson());if(!connector.commit())return 6;QObject::connect(&app,&QCoreApplication::aboutToQuit,&app,[&]{QFile::remove(HalabTools::profile()+"/connector.json");});}QTemporaryDir previewState;Window w(args.contains("--preview")?previewState.path()+"/downloads.json":QString());QObject::connect(&server,&QTcpServer::newConnection,&w,[&]{while(server.hasPendingConnections()){auto socket=server.nextPendingConnection();auto buffer=std::make_shared<QByteArray>();QTimer::singleShot(5000,socket,[socket]{socket->disconnectFromHost();});QObject::connect(socket,&QTcpSocket::disconnected,socket,&QObject::deleteLater);QObject::connect(socket,&QTcpSocket::readyRead,&w,[&,socket,buffer]{buffer->append(socket->readAll());if(buffer->size()>65536){socket->disconnectFromHost();return;}if(!buffer->contains('\n'))return;auto request=QJsonDocument::fromJson(buffer->left(buffer->indexOf('\n'))).object();QJsonObject answer;if(request["_token"].toString()!=connectorToken)answer={{"ok",false},{"error","Unauthorized connector request"}};else answer=w.receiveExternal(request);socket->write(QJsonDocument(answer).toJson(QJsonDocument::Compact)+"\n");socket->flush();socket->disconnectFromHost();});}});if(args.contains("--language")){int lang=args.indexOf("--language");if(lang+1<args.size())w.changeLanguage(args[lang+1]);}QSystemTrayIcon tray(&app);QMenu trayMenu;QPixmap trayImage(64,64);trayImage.fill(Qt::transparent);{QPainter painter(&trayImage);painter.setRenderHint(QPainter::Antialiasing);painter.setBrush(QColor("#118578"));painter.setPen(Qt::NoPen);painter.drawRoundedRect(2,2,60,60,12,12);painter.setPen(Qt::white);painter.setFont(QFont("Segoe UI",32,QFont::Bold));painter.drawText(trayImage.rect(),Qt::AlignCenter,"H");}QIcon appIcon(trayImage);w.setWindowIcon(appIcon);tray.setIcon(appIcon);tray.setToolTip("Halab Download Manager");auto openTray=trayMenu.addAction(L::text("Open Halab Download Manager"));QObject::connect(openTray,&QAction::triggered,&w,[&]{w.showNormal();w.raise();w.activateWindow();});trayMenu.addSeparator();auto exitTray=trayMenu.addAction(L::text("Exit"));QObject::connect(exitTray,&QAction::triggered,&app,&QCoreApplication::quit);QObject::connect(&tray,&QSystemTrayIcon::activated,&w,[&](QSystemTrayIcon::ActivationReason reason){if(reason==QSystemTrayIcon::Trigger||reason==QSystemTrayIcon::DoubleClick){w.showNormal();w.raise();w.activateWindow();}});tray.setContextMenu(&trayMenu);bool background=QSystemTrayIcon::isSystemTrayAvailable()&&!args.contains("--preview");w.setProperty("backgroundCapable",background);if(background){app.setQuitOnLastWindowClosed(false);tray.show();}QObject::connect(&app,&QCoreApplication::aboutToQuit,&w,[&]{w.shutdown();});QObject::connect(&app,&QGuiApplication::commitDataRequest,&w,[&](QSessionManager&){w.shutdown();});if(!args.contains("--background")||!background)w.show();if(args.contains("--preview")){int p=args.indexOf("--preview");if(p+1<args.size())QTimer::singleShot(500,&app,[&]{if(args.contains("--preview-menu")){auto menu=w.findChild<QMenu*>("downloadsMenu");menu->popup(w.mapToGlobal(QPoint(150,30)));QCoreApplication::processEvents();menu->grab().save(args[p+1]);menu->hide();}else w.grab().save(args[p+1]);app.quit();});}if(args.contains("--tray-check")){QTimer::singleShot(350,&app,[&]{bool ok=background&&tray.isVisible()&&!w.isVisible();w.showNormal();w.close();ok=ok&&!w.isVisible();QTextStream(stdout)<<"TRAY available="<<background<<" icon="<<tray.isVisible()<<" hiddenAfterClose="<<!w.isVisible()<<Qt::endl;app.exit(ok?0:1);});}if(args.contains("--smoke"))QTimer::singleShot(1500,&app,&QCoreApplication::quit);return app.exec();}
